function earliestSecondToMarkIndices(nums, changeIndices) {
  const n = nums.length;
  const m = changeIndices.length;

  const canFinish = (seconds) => {
    const last = new Array(n + 1).fill(-1);
    for (let s = 0; s < seconds; s++) last[changeIndices[s]] = s;
    let free = 0;
    let marked = 0;
    for (let s = 0; s < seconds; s++) {
      const index = changeIndices[s];
      if (last[index] !== s) {
        free++;
        continue;
      }
      if (free < nums[index - 1]) return false;
      free -= nums[index - 1];
      marked++;
    }
    return marked === n;
  };

  let low = 1;
  let high = m;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (canFinish(mid)) high = mid;
    else low = mid + 1;
  }
  return canFinish(low) ? low : -1;
}

brute:
function earliestSecondToMarkIndices(nums, changeIndices) {
  // Explore every reachable state (values left, marks made) second by second.
  const n = nums.length;
  let states = new Set([JSON.stringify([nums.slice(), new Array(n).fill(false)])]);
  for (let s = 0; s < changeIndices.length; s++) {
    const next = new Set();
    for (const key of states) {
      const [values, marks] = JSON.parse(key);
      next.add(key);
      for (let i = 0; i < n; i++) {
        if (values[i] > 0) {
          const lowered = values.slice();
          lowered[i]--;
          next.add(JSON.stringify([lowered, marks]));
        }
      }
      const target = changeIndices[s] - 1;
      if (values[target] === 0 && !marks[target]) {
        const nextMarks = marks.slice();
        nextMarks[target] = true;
        if (nextMarks.every(Boolean)) return s + 1;
        next.add(JSON.stringify([values, nextMarks]));
      }
    }
    states = next;
  }
  return -1;
}

