function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 3);
    const nums = Array.from({ length: n }, () => (rand() < 0.3 ? 0 : int(0, 3)));
    const m = int(1, 10);
    const changeIndices = Array.from({ length: m }, () => int(1, n));
    return [nums, changeIndices];
  }
  const mode = int(0, 2);
  const n = mode === 0 ? int(1500, 2000) : int(50, 400);
  const nums = Array.from({ length: n }, () => (mode === 0 ? 0 : mode === 1 ? int(0, 6) : (rand() < 0.02 ? int(1, 1e9) : int(0, 3))));
  const m = int(1800, 2000);
  const changeIndices = Array.from({ length: m }, () => int(1, n));
  // Usually make sure every position appears, late enough to leave time for the decrements.
  if (rand() < 0.85) {
    const order = Array.from({ length: n }, (_, i) => i + 1);
    for (let i = order.length - 1; i > 0; i--) {
      const j = int(0, i);
      [order[i], order[j]] = [order[j], order[i]];
    }
    const start = Math.max(0, m - n - int(0, Math.floor(m / 3)));
    order.slice(0, m).forEach((position, k) => { changeIndices[Math.min(m - 1, start + k)] = position; });
  }
  return [nums, changeIndices];
}
